    question: "Convert the sentence into Interrogative sentence.\n“Growing plants that require very little attention has become almost a given for those who desire verdant comfort at home.”\n\nRead the passage and answer the following questions:\nIn an age when city residents often complain about their lack of time, growing plants that require very little attention has become almost a given for those who desire verdant comfort at home. Some varieties, blessed with exceptional toughness, can survive with minimal care, reducing the worry that often comes with gardening.\nThe snake plant (Sansevieria trifasciata), for example, is nearly unbreakable. It flourishes in different light settings and tolerates irregular watering without losing its firm, elegant form. Similarly, pothos (Epipremnum aureum), with its rich trailing leaves, adjusts easily to both low-light corners and brighter areas, continuing photosynthesis with steady persistence.\nAnother notable choice is aloe vera, whose fleshy leaves store water, making frequent watering unnecessary. Beyond its decorative appeal, aloe vera offers medicinal value, as its gel is prized for soothing and healing the skin. Even the ZZ plant (Zamioculcas zamiifolia), as if carved from glossy green wax, thrives on neglect, enduring long dry spells and dim light without capitulating to decay.\nThe charm of these plants lies not only in the beauty they add but also in the message they quietly convey: resilience can be just as captivating as delicacy. By nurturing them, one enters a calm partnership in which human care plays a secondary role, while nature’s own processes sustain life with effortless grace.",
