    question: "In the passage, the phrase “commodification of art” most nearly means:\n\nRead the following passage and answer the questions based on the passage:\n\nArt, across its many expressions—painting, theatre, literature, music, and more—moves beyond practical usefulness into the spheres of meaning, emotion, and transformation. Its place in society is not merely ornamental or entertaining; it functions as a medium of critique, a repository of shared memory, and an engine of cultural change. At its centre, art unsettles reality by reshaping how we see. Whether through the disorienting imagery of surrealism or the unsettling textures of experimental sound, art pulls the viewer out of comfort and demands renewed attention to the world. In doing so, art becomes not only aesthetic but an epistemic act—one that questions accepted “truths,” disrupts dominant frameworks, and widens the space for voices kept at the margins.\n\nAcross history, art has also acted as a record of civilisations, preserving within its forms the desires, fears, conflicts, and ideals of a given age. From sacred temple murals to rebellious street art on crumbling city walls, creative work becomes a language through which authority, resistance, and identity are negotiated at once. This deep historical grounding makes art vital for understanding not only what societies produce, but what they prize and what they dread. In contemporary democracies, art often takes on a political charge. Where speech is curtailed, art can carry dissent; where logic falls short, it can generate empathy. Satire, documentary cinema, and performance frequently communicate what cannot be stated directly, using symbol, metaphor, and suggestion to evade suppression. Yet this very power exposes art to risk—censorship, marketing pressures, and ideological capture. When art loses autonomy, it can slide into propaganda or empty prestige, stripped of its questioning force.\n\nArt also performs a social role by building community and inviting self-examination at the same time. Participatory forms—street theatre, public installations, folk practices—blur the line between maker and viewer, broadening access to aesthetic experience. Meanwhile, private engagement with a poem or painting may trigger insight, catharsis, or moral reflection. However, in an algorithm-driven era where visibility and virality often decide worth, art increasingly faces the commodification of art. The aesthetic is repackaged as a spectacle for quick consumption, detached from complexity, nuance, and risk. The challenge, therefore, is to protect artistic integrity against market and media forces that may reduce it to banality. Ultimately, art’s role is neither fixed nor singular: it is a dialectical energy—both mirror and blueprint, disruptive and restorative. To protect art is to protect the human capacity to feel, to question, and to reimagine.",
