// =====================================================
// HELPERS
// =====================================================
const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5);
const getRandom = (arr, n) => shuffle(arr).slice(0, n);

// Time per section (seconds)
const SECTION_TIME = 900; // 15 minutes

/**
 * Build paper grouped by SECTION.
 * English section: 20 random English + 5 random Comprehension = 25
 */
const buildSectionedPaper = (lang) => {
  const math = lang === "hi" ? mathHi : mathEn;
  const reasoning = lang === "hi" ? reasoningHi : reasoningEn;
  const gk = lang === "hi" ? gkHi : gkEn;

  const sections = [
    {
      id: 1,
      name: { hi: "गणित", en: "Mathematics" },
      color: "#3b82f6",
      questions: getRandom(math, 25),
    },
    {
      id: 2,
      name: { hi: "तर्कशक्ति", en: "Reasoning" },
      color: "#8b5cf6",
      questions: getRandom(reasoning, 25),
    },
    {
      id: 3,
      name: { hi: "सामान्य ज्ञान", en: "General Knowledge" },
      color: "#f59e0b",
      questions: getRandom(gk, 25),
    },
    {
      id: 4,
      name: { hi: "अंग्रेजी", en: "English" },
      color: "#10b981",
      questions: [
        ...getRandom(englishQuestions, 20), // 20 random English
        ...getRandom(comprehensionQuestions, 5), // 5 random Comprehension
      ],
    },
  ];

  return sections;
};

// =====================================================
// MAIN COMPONENT
// =====================================================
export default function SSCCGLMockTest() {
  const [started, setStarted] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const [language, setLanguage] = useState("hi");
  const [sections, setSections] = useState([]);
  const [currentSection, setCurrentSection] = useState(0);
  const [current, setCurrent] = useState(0);
  const [sectionTime, setSectionTime] = useState(SECTION_TIME);
  const [sectionLocked, setSectionLocked] = useState([
    false,
    false,
    false,
    false,
  ]);
  const [answers, setAnswers] = useState({});
  const [score, setScore] = useState({
    correct: 0,
    wrong: 0,
    notAttempted: 0,
    finalScore: 0,
  });
  const [resultDetails, setResultDetails] = useState([]);
  const [showTimerWarning, setShowTimerWarning] = useState(false);

  // Timer for current section
  useEffect(() => {
    if (
      started &&
      !submitted &&
      sectionTime > 0 &&
      !sectionLocked[currentSection]
    ) {
      const t = setInterval(() => {
        setSectionTime((p) => {
          if (p <= 60) setShowTimerWarning(true);
          return p - 1;
        });
      }, 1000);
      return () => clearInterval(t);
    }
    if (
      sectionTime === 0 &&
      started &&
      !submitted &&
      !sectionLocked[currentSection]
    ) {
      handleSubmitSection(true);
    }
    // eslint-disable-next-line
  }, [started, submitted, sectionTime, currentSection]);

  const startExam = () => {
    const paper = buildSectionedPaper(language);
    setSections(paper);
    setStarted(true);
    setSubmitted(false);
    setCurrentSection(0);
    setCurrent(0);
    setSectionTime(SECTION_TIME);
    setSectionLocked([false, false, false, false]);
    setAnswers({});
    setScore({ correct: 0, wrong: 0, notAttempted: 0, finalScore: 0 });
    setResultDetails([]);
    setShowTimerWarning(false);
  };

  const answerKey = (secIdx, qIdx) => `${secIdx}-${qIdx}`;

  const handleSelect = (secIdx, qIdx, option) => {
    if (sectionLocked[secIdx]) return;
    setAnswers((prev) => ({ ...prev, [answerKey(secIdx, qIdx)]: option }));
  };

  const handleSubmitSection = (auto = false) => {
    const newLocked = [...sectionLocked];
    newLocked[currentSection] = true;
    setSectionLocked(newLocked);
    setShowTimerWarning(false);

    if (currentSection < sections.length - 1) {
      setCurrentSection(currentSection + 1);
      setCurrent(0);
      setSectionTime(SECTION_TIME);
    } else {
      finalizeResult(newLocked);
    }
    // eslint-disable-next-line
  };

  const finalizeResult = (lockedArr) => {
    let correctCount = 0;
    let wrongCount = 0;
    let notAttemptedCount = 0;
    const details = [];

    sections.forEach((sec, secIdx) => {
      sec.questions.forEach((q, qIdx) => {
        const userAns = answers[answerKey(secIdx, qIdx)];
        const isCorrect = userAns === q.answer;
        const attempted = !!userAns;

        if (isCorrect) correctCount++;
        else if (attempted) wrongCount++;
        else notAttemptedCount++;

        details.push({
          question: q.question,
          correctAnswer: q.answer,
          userAnswer:
            userAns ||
            (language === "hi" ? "प्रयास नहीं किया" : "Not Attempted"),
          isCorrect,
          attempted,
          section: sec.id,
          sectionName: sec.name,
        });
      });
    });

    // Negative marking: +2 per correct, -0.50 per wrong, 0 for unattempted
    const finalScore = correctCount * 2 - wrongCount * 0.5;

    setScore({
      correct: correctCount,
      wrong: wrongCount,
      notAttempted: notAttemptedCount,
      finalScore: finalScore,
    });
    setResultDetails(details);
    setSubmitted(true);
  };

  const toggleLanguage = () => {
    if (!started) setLanguage(language === "hi" ? "en" : "hi");
  };

  const getText = (key) => {
    const t = {
      title: { hi: "📝 SSC CGL Mock Test", en: "📝 SSC CGL Mock Test" },
      subtitle: {
        hi: "कर्मचारी चयन आयोग - CGL",
        en: "Staff Selection Commission - CGL",
      },
      questions: { hi: "📝 प्रश्न", en: "📝 Questions" },
      time: { hi: "⏱️ समय", en: "⏱️ Time" },
      marks: { hi: "🎯 कुल अंक", en: "🎯 Total Marks" },
      instructions: { hi: "📋 निर्देश:", en: "📋 Instructions:" },
      compulsory: {
        hi: "सभी प्रश्न अनिवार्य हैं",
        en: "All questions are compulsory",
      },
      eachMarks: {
        hi: "प्रत्येक प्रश्न 2 अंक का है",
        en: "Each question carries 2 marks",
      },
      negativeMarking: {
        hi: "नेगेटिव मार्किंग: प्रत्येक गलत उत्तर पर 0.50 अंक काटे जाते हैं",
        en: "Negative Marking: 0.50 marks deducted per wrong answer",
      },
      sessions: {
        hi: "खंडवार समय: गणित (15 मिनट) → तर्कशक्ति (15 मिनट) → सा.ज्ञान (15 मिनट) → अंग्रेजी (15 मिनट)",
        en: "Sectional Time: Math (15 min) → Reasoning (15 min) → GK (15 min) → English (15 min)",
      },
      sectionRule: {
        hi: "⚠️ एक बार अनुभाग जमा करने के बाद, आप वापस नहीं जा सकते।",
        en: "⚠️ Once a section is submitted, you cannot return to it.",
      },
      start: { hi: "🚀 परीक्षा शुरू करें", en: "🚀 Start Exam" },
      prev: { hi: "⬅ पिछला", en: "⬅ Prev" },
      next: { hi: "अगला ➡", en: "Next ➡" },
      submitSection: {
        hi: "📤 अनुभाग जमा करें",
        en: "📤 Submit Section",
      },
      submitTest: { hi: "✅ परीक्षा जमा करें", en: "✅ Submit Test" },
      answered: { hi: "उत्तर दिए:", en: "Answered:" },
      navigator: { hi: "प्रश्न नेविगेटर", en: "Question Navigator" },
      answeredS: { hi: "🟢 उत्तर दिया", en: "🟢 Answered" },
      currentS: { hi: "🔵 वर्तमान", en: "🔵 Current" },
      unansweredS: { hi: "⚪ अनुत्तरित", en: "⚪ Unanswered" },
      lockedS: { hi: "🔒 लॉक", en: "🔒 Locked" },
      congrats: { hi: "🎉 बधाई हो!", en: "🎉 Congratulations!" },
      practice: { hi: "📖 अभ्यास जारी रखें!", en: "📖 Keep Practicing!" },
      passed: { hi: "✔️ उत्तीर्ण", en: "✔️ Passed" },
      failed: { hi: "❌ अनुत्तीर्ण", en: "❌ Failed" },
      review: { hi: "📋 उत्तर समीक्षा", en: "📋 Answer Review" },
      yourAnswer: { hi: "आपका उत्तर:", en: "Your Answer:" },
      correctAnswer: { hi: "सही उत्तर:", en: "Correct Answer:" },
      newTest: { hi: "🔄 नई परीक्षा लें", en: "🔄 Take New Test" },
      warning: {
        hi: "⚠️ 1 मिनट से कम समय शेष!",
        en: "⚠️ Less than 1 minute remaining!",
      },
      download: {
        hi: "📥 परिणाम डाउनलोड करें",
        en: "📥 Download Result",
      },
      correct: { hi: "✔ सही", en: "✔ Correct" },
      wrong: { hi: "✖ गलत", en: "✖ Wrong" },
      notAttempted: { hi: "⚪ अनुत्तरित", en: "⚪ Not Attempted" },
      langLine: {
        hi: "भाषा: हिन्दी • नेगेटिव मार्किंग: −0.50 प्रति गलत उत्तर",
        en: "Language: English • Negative Marking: −0.50 per wrong answer",
      },
      sectionLabel: { hi: "अनुभाग", en: "Section" },
      of: { hi: "का", en: "of" },
      sectionEnd: { hi: "अनुभाग समाप्त!", en: "Section Ended!" },
      sectionEndMsg: {
        hi: "इस अनुभाग का समय समाप्त हो गया है। अगले अनुभाग पर जा रहे हैं...",
        en: "Time for this section has ended. Moving to next section...",
      },
      sectionSubmitted: {
        hi: "✅ अनुभाग जमा हो गया! अगला अनुभाग शुरू हो रहा है...",
        en: "✅ Section submitted! Next section starting...",
      },
      finalSubmitConfirm: {
        hi: "यह अंतिम अनुभाग है। क्या आप परीक्षा जमा करना चाहते हैं?",
        en: "This is the last section. Submit the test?",
      },
      submitSectionConfirm: {
        hi: "क्या आप इस अनुभाग को जमा करना चाहते हैं? आप वापस नहीं जा सकेंगे।",
        en: "Submit this section? You cannot return afterward.",
      },
      yes: { hi: "हाँ", en: "Yes" },
      no: { hi: "नहीं", en: "No" },
    };
    return t[key]?.[language] || t[key]?.["en"] || key;
  };

  // ============ HOME ============
  if (!started) {
    return (
      <div style={styles.homeWrapper}>
        <div style={styles.homeCard}>
          <div style={{ fontSize: "48px", marginBottom: "5px" }}>📝</div>
          <h1 style={styles.homeTitle}>{getText("title")}</h1>
          <p style={styles.homeSub}>{getText("subtitle")}</p>
          <div style={styles.divider}></div>

          <div style={styles.langRow}>
            <span
              style={{
                ...styles.langLabel,
                fontWeight: language === "hi" ? "700" : "400",
                color: language === "hi" ? "#0f0c29" : "#999",
              }}
            >
              हिन्दी
            </span>
            <button
              onClick={toggleLanguage}
              style={{
                ...styles.toggleBtn,
                background: language === "hi" ? "#302b63" : "#4a90d9",
              }}
            >
              <div
                style={{
                  ...styles.toggleKnob,
                  left: language === "hi" ? "3px" : "27px",
                }}
              ></div>
            </button>
            <span
              style={{
                ...styles.langLabel,
                fontWeight: language === "en" ? "700" : "400",
                color: language === "en" ? "#0f0c29" : "#999",
              }}
            >
              English
            </span>
          </div>

          <div style={styles.statGrid}>
            <div style={styles.statBox}>
              <div style={styles.statLabel}>{getText("questions")}</div>
              <div style={styles.statValue}>100</div>
            </div>
            <div style={styles.statBox}>
              <div style={styles.statLabel}>{getText("time")}</div>
              <div style={styles.statValue}>60 min</div>
            </div>
            <div style={styles.statBox}>
              <div style={styles.statLabel}>{getText("marks")}</div>
              <div style={styles.statValue}>200</div>
            </div>
          </div>

          <div style={styles.instructionsBox}>
            <strong>{getText("instructions")}</strong>
            <ul style={{ margin: "5px 0 0 0", paddingLeft: "18px" }}>
              <li>{getText("compulsory")}</li>
              <li>{getText("eachMarks")}</li>
              <li style={{ color: "#dc2626", fontWeight: "600" }}>
                ⚠️ {getText("negativeMarking")}
              </li>
              <li>{getText("sessions")}</li>
              <li style={{ color: "#dc2626", fontWeight: "600" }}>
                {getText("sectionRule")}
              </li>
            </ul>
          </div>

          <button onClick={startExam} style={styles.startBtn}>
            {getText("start")}
          </button>
        </div>
        <style>{animStyles}</style>
      </div>
    );
  }

  // ============ RESULT ============
  if (submitted) {
    const total = resultDetails.length;
    const maxMarks = total * 2; // 2 marks per question
    const { correct, wrong, notAttempted, finalScore } = score;

    const percentage = ((finalScore / maxMarks) * 100).toFixed(2);
    const isPassed = Number(percentage) >= 60;

    return (
      <div style={styles.resultWrapper}>
        <div style={styles.resultContainer}>
          <div style={styles.resultCard}>
            <div
              style={{
                fontSize: "14px",
                color: "#718096",
                marginBottom: "10px",
              }}
            >
              📖 {getText("practice")}
            </div>
            <div
              style={{
                ...styles.bigCircle,
                background: isPassed ? "#dcfce7" : "#fee2e2",
              }}
            >
              {isPassed ? "✅" : "📝"}
            </div>

            {/* Final Score (with negative marking) */}
            <div style={styles.scoreBig}>
              {finalScore.toFixed(2)}{" "}
              <span style={{ fontSize: "22px", color: "#888" }}>
                / {maxMarks}
              </span>
            </div>

            <div
              style={{
                fontSize: "18px",
                color: isPassed ? "#16a34a" : "#dc2626",
                fontWeight: "700",
                marginTop: "4px",
              }}
            >
              {percentage}% {isPassed ? getText("passed") : getText("failed")}
            </div>
            <div style={styles.langLine}>{getText("langLine")}</div>

            <div style={styles.statRow}>
              <div
                style={{
                  ...styles.pill,
                  background: "#dcfce7",
                  color: "#166534",
                }}
              >
                ✔ {getText("correct")}: {correct} (+{correct * 2})
              </div>
              <div
                style={{
                  ...styles.pill,
                  background: "#fee2e2",
                  color: "#991b1b",
                }}
              >
                ✖ {getText("wrong")}: {wrong} (−{(wrong * 0.5).toFixed(2)})
              </div>
              <div
                style={{
                  ...styles.pill,
                  background: "#fef3c7",
                  color: "#92400e",
                }}
              >
                ⚪ {getText("notAttempted")}: {notAttempted}
              </div>
            </div>

            {/* Negative marking notice */}
            <div
              style={{
                marginTop: "14px",
                fontSize: "12px",
                color: "#92400e",
                background: "#fef3c7",
                border: "1px solid #fde68a",
                padding: "8px 12px",
                borderRadius: "8px",
                fontWeight: "600",
              }}
            >
              ⚠️ {getText("negativeMarking")}
            </div>

            <button
              onClick={() => window.print()}
              style={styles.downloadBtn}
            >
              {getText("download")}
            </button>
          </div>

          <div style={styles.reviewCard}>
            <h2 style={styles.reviewTitle}>📋 {getText("review")}</h2>
            {resultDetails.map((item, index) => (
              <div
                key={index}
                style={{
                  ...styles.reviewItem,
                  background: "#fffbeb",
                  borderLeft: `4px solid ${
                    item.isCorrect
                      ? "#22c55e"
                      : item.attempted
                      ? "#ef4444"
                      : "#f59e0b"
                  }`,
                }}
              >
                <div style={styles.reviewQ}>
                  Q{index + 1}. <QuestionText text={item.question} />
                </div>
                <div style={styles.reviewAns}>
                  <div>
                    <strong>{getText("yourAnswer")} </strong>
                    <span
                      style={{
                        color: item.isCorrect ? "#16a34a" : "#dc2626",
                      }}
                    >
                      <MathText text={item.userAnswer} />
                    </span>
                  </div>
                  <div>
                    <strong>{getText("correctAnswer")} </strong>
                    <span
                      style={{ color: "#16a34a", fontStyle: "italic" }}
                    >
                      <MathText text={item.correctAnswer} />
                    </span>
                  </div>
                </div>
                <div style={styles.reviewStatus}>
                  {item.isCorrect ? "✅" : item.attempted ? "❌" : "⚪"}
                </div>
              </div>
            ))}
          </div>

          <div style={{ textAlign: "center", marginTop: "20px" }}>
            <button
              onClick={() => {
                setStarted(false);
                setSubmitted(false);
                setAnswers({});
                setResultDetails([]);
                setSectionTime(SECTION_TIME);
                setShowTimerWarning(false);
                setSections([]);
                setCurrent(0);
                setCurrentSection(0);
                setSectionLocked([false, false, false, false]);
                setScore({
                  correct: 0,
                  wrong: 0,
                  notAttempted: 0,
                  finalScore: 0,
                });
              }}
              style={styles.startBtn}
            >
              {getText("newTest")}
            </button>
          </div>
        </div>
        <style>{animStyles}</style>
      </div>
    );
  }

  // ============ EXAM ============
  const sec = sections[currentSection];
  if (!sec) return null;
  const q = sec.questions[current] || { question: "", option: [] };
  const answeredCount = sec.questions.reduce(
    (acc, _, qIdx) =>
      answers[answerKey(currentSection, qIdx)] ? acc + 1 : acc,
    0
  );
  const isLastSection = currentSection === sections.length - 1;

  const confirmSubmitSection = () => {
    const msg = isLastSection
      ? getText("finalSubmitConfirm")
      : getText("submitSectionConfirm");
    if (window.confirm(msg)) {
      handleSubmitSection(false);
    }
  };

  return (
    <div style={styles.examWrapper}>
      <div style={styles.examContainer}>
        {/* Top bar */}
        <div style={styles.topBar}>
          <div style={{ flex: 1 }}>
            <p style={styles.qCounter}>
              {getText("sectionLabel")} {currentSection + 1}/
              {sections.length} • Q{current + 1}/{sec.questions.length}
            </p>
            <p style={styles.qSubCounter}>
              {getText("answered")} {answeredCount}/{sec.questions.length}
            </p>
            <p
              style={{
                margin: "4px 0 0",
                fontSize: "11px",
                color: "white",
                fontWeight: "700",
                background: sec.color,
                display: "inline-block",
                padding: "3px 10px",
                borderRadius: "10px",
              }}
            >
              {sec.name[language]}
            </p>
          </div>
          <div
            style={{
              ...styles.timer,
              color: sectionTime < 60 ? "#fc8181" : "#0f0c29",
            }}
          >
            <span style={{ fontSize: "16px" }}>⏱️</span>
            <span>
              {Math.floor(sectionTime / 60)}:
              {String(sectionTime % 60).padStart(2, "0")}
            </span>
          </div>
        </div>

        {/* Section progress bar */}
        <div style={styles.sectionProgressWrap}>
          {sections.map((s, i) => (
            <div
              key={i}
              style={{
                ...styles.sectionProgressItem,
                background:
                  i < currentSection
                    ? "#22c55e"
                    : i === currentSection
                    ? s.color
                    : "#e2e8f0",
                color: i <= currentSection ? "white" : "#4a5568",
              }}
            >
              {i < currentSection ? "🔒" : i + 1}. {s.name[language]}
            </div>
          ))}
        </div>

        {/* Question card */}
        <div style={styles.questionCard}>
          <h3 style={styles.questionText}>
            <QuestionText text={q.question} />
          </h3>
          <div style={{ marginTop: "5px" }}>
            {q.option &&
              q.option.map((op, idx) => {
                const selected =
                  answers[answerKey(currentSection, current)] === op;
                return (
                  <div
                    key={idx}
                    style={{
                      ...styles.option,
                      backgroundColor: selected ? "#ebf8ff" : "#f7fafc",
                      border: selected
                        ? "2px solid #302b63"
                        : "2px solid transparent",
                    }}
                    onClick={() =>
                      handleSelect(currentSection, current, op)
                    }
                  >
                    <input
                      type="radio"
                      checked={selected}
                      onChange={() => {}}
                      style={{
                        marginRight: "10px",
                        width: "16px",
                        height: "16px",
                      }}
                    />
                    <label style={styles.optionLabel}>
                      <MathText text={op} />
                    </label>
                  </div>
                );
              })}
          </div>
        </div>

        {/* Nav */}
        <div style={styles.navRow}>
          <div style={{ display: "flex", gap: "8px" }}>
            <button
              onClick={() => setCurrent(Math.max(0, current - 1))}
              disabled={current === 0}
              style={{
                ...styles.navBtn,
                backgroundColor: current === 0 ? "#e2e8f0" : "#302b63",
                color: current === 0 ? "#a0aec0" : "white",
                cursor: current === 0 ? "not-allowed" : "pointer",
              }}
            >
              {getText("prev")}
            </button>
            <button
              onClick={() =>
                setCurrent(
                  Math.min(sec.questions.length - 1, current + 1)
                )
              }
              disabled={current === sec.questions.length - 1}
              style={{
                ...styles.navBtn,
                backgroundColor:
                  current === sec.questions.length - 1
                    ? "#e2e8f0"
                    : "#302b63",
                color:
                  current === sec.questions.length - 1
                    ? "#a0aec0"
                    : "white",
                cursor:
                  current === sec.questions.length - 1
                    ? "not-allowed"
                    : "pointer",
              }}
            >
              {getText("next")}
            </button>
          </div>
          <button onClick={confirmSubmitSection} style={styles.submitBtn}>
            {isLastSection
              ? getText("submitTest")
              : getText("submitSection")}
          </button>
        </div>

        {/* Navigator */}
        <div style={styles.navigatorCard}>
          <p style={styles.navTitle}>{getText("navigator")}</p>
          <div style={styles.navGrid}>
            {sec.questions.map((_, idx) => {
              const isAnswered = !!answers[answerKey(currentSection, idx)];
              const isCurrent = idx === current;
              return (
                <button
                  key={idx}
                  onClick={() => setCurrent(idx)}
                  style={{
                    ...styles.navNum,
                    backgroundColor: isAnswered
                      ? "#48bb78"
                      : isCurrent
                      ? sec.color
                      : "#e2e8f0",
                    color:
                      isAnswered || isCurrent ? "white" : "#4a5568",
                    border: isCurrent
                      ? `2px solid ${sec.color}`
                      : "none",
                  }}
                >
                  {idx + 1}
                </button>
              );
            })}
          </div>
          <div style={styles.legendRow}>
            <span>{getText("answeredS")}</span>
            <span>{getText("currentS")}</span>
            <span>{getText("unansweredS")}</span>
            <span>🔒 {getText("lockedS")}</span>
          </div>
        </div>

        {showTimerWarning && (
          <div style={styles.timerWarning}>{getText("warning")}</div>
        )}
      </div>
      <style>{animStyles}</style>
    </div>
  );
}

// =====================================================
// STYLES
// =====================================================
const styles = {
  homeWrapper: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background:
      "linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%)",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    padding: "20px",
  },
  homeCard: {
    backgroundColor: "white",
    padding: "25px 20px",
    borderRadius: "16px",
    boxShadow: "0 20px 60px rgba(0,0,0,0.6)",
    textAlign: "center",
    maxWidth: "500px",
    width: "100%",
  },
  homeTitle: {
    color: "#0f0c29",
    marginBottom: "3px",
    fontSize: "22px",
    fontWeight: "700",
  },
  homeSub: { color: "#666", fontSize: "12px", marginBottom: "15px" },
  divider: {
    height: "3px",
    background: "linear-gradient(90deg, #0f0c29, #302b63)",
    margin: "10px auto",
    width: "60px",
  },
  langRow: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    gap: "12px",
    margin: "15px 0",
  },
  langLabel: { fontSize: "14px" },
  toggleBtn: {
    width: "50px",
    height: "26px",
    borderRadius: "13px",
    border: "none",
    cursor: "pointer",
    position: "relative",
    transition: "all 0.3s ease",
  },
  toggleKnob: {
    width: "20px",
    height: "20px",
    borderRadius: "50%",
    background: "white",
    position: "absolute",
    top: "3px",
    transition: "all 0.3s ease",
    boxShadow: "0 2px 4px rgba(0,0,0,0.2)",
  },
  statGrid: {
    display: "grid",
    gridTemplateColumns: "1fr 1fr 1fr",
    gap: "8px",
    marginTop: "10px",
  },
  statBox: {
    backgroundColor: "#e8f0fe",
    padding: "10px",
    borderRadius: "10px",
  },
  statLabel: { fontSize: "10px", color: "#666" },
  statValue: { fontSize: "18px", fontWeight: "bold", color: "#0f0c29" },
  instructionsBox: {
    backgroundColor: "#f8f9fa",
    padding: "10px",
    borderRadius: "10px",
    marginTop: "10px",
    fontSize: "12px",
    color: "#555",
    textAlign: "left",
  },
  startBtn: {
    padding: "14px 40px",
    fontSize: "18px",
    fontWeight: "bold",
    background: "linear-gradient(135deg, #0f0c29 0%, #302b63 100%)",
    color: "white",
    border: "none",
    borderRadius: "50px",
    cursor: "pointer",
    marginTop: "20px",
    width: "100%",
    transition: "transform 0.3s, box-shadow 0.3s",
    boxShadow: "0 4px 15px rgba(48, 43, 99, 0.4)",
  },
  resultWrapper: {
    minHeight: "100vh",
    background: "#f5f7fa",
    padding: "15px",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
  },
  resultContainer: { maxWidth: "800px", margin: "0 auto" },
  resultCard: {
    backgroundColor: "white",
    borderRadius: "16px",
    padding: "25px 20px",
    boxShadow: "0 10px 40px rgba(0,0,0,0.1)",
    textAlign: "center",
    marginBottom: "20px",
  },
  bigCircle: {
    width: "80px",
    height: "80px",
    borderRadius: "50%",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    margin: "15px auto",
    fontSize: "32px",
  },
  scoreBig: { fontSize: "44px", fontWeight: "bold", color: "#0f0c29" },
  langLine: { marginTop: "10px", fontSize: "13px", color: "#718096" },
  statRow: {
    display: "flex",
    gap: "8px",
    marginTop: "18px",
    flexWrap: "wrap",
    justifyContent: "center",
  },
  pill: {
    padding: "10px 16px",
    borderRadius: "10px",
    fontSize: "13px",
    fontWeight: "700",
    flex: 1,
    minWidth: "110px",
  },
  downloadBtn: {
    marginTop: "18px",
    padding: "12px 32px",
    fontSize: "15px",
    fontWeight: "bold",
    background: "#16a34a",
    color: "white",
    border: "none",
    borderRadius: "50px",
    cursor: "pointer",
    boxShadow: "0 4px 15px rgba(22, 163, 74, 0.4)",
  },
  reviewCard: {
    backgroundColor: "white",
    borderRadius: "16px",
    padding: "20px 15px",
    boxShadow: "0 10px 40px rgba(0,0,0,0.1)",
  },
  reviewTitle: {
    borderBottom: "2px solid #eee",
    paddingBottom: "12px",
    marginBottom: "15px",
    fontSize: "18px",
    color: "#2d3748",
  },
  reviewItem: {
    padding: "12px 15px",
    marginBottom: "12px",
    borderRadius: "8px",
    position: "relative",
  },
  reviewQ: {
    fontSize: "14px",
    color: "#2d3748",
    marginBottom: "8px",
    paddingRight: "30px",
  },
  reviewAns: {
    fontSize: "13px",
    display: "flex",
    flexDirection: "column",
    gap: "3px",
  },
  reviewStatus: {
    position: "absolute",
    top: "12px",
    right: "14px",
    fontSize: "16px",
  },
  examWrapper: {
    minHeight: "100vh",
    background: "#f5f7fa",
    padding: "10px",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
  },
  examContainer: { maxWidth: "800px", margin: "0 auto" },
  topBar: {
    backgroundColor: "white",
    borderRadius: "12px",
    padding: "10px 14px",
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
    marginBottom: "10px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  },
  qCounter: { margin: "0", fontSize: "11px", color: "#718096" },
  qSubCounter: { margin: "2px 0 0", fontSize: "10px", color: "#a0aec0" },
  timer: {
    fontSize: "20px",
    fontWeight: "bold",
    display: "flex",
    alignItems: "center",
    gap: "6px",
  },
  sectionProgressWrap: {
    display: "flex",
    gap: "6px",
    marginBottom: "10px",
    flexWrap: "wrap",
  },
  sectionProgressItem: {
    flex: 1,
    minWidth: "120px",
    padding: "8px 10px",
    borderRadius: "10px",
    fontSize: "11px",
    fontWeight: "700",
    textAlign: "center",
    transition: "all 0.3s ease",
  },
  questionCard: {
    backgroundColor: "white",
    borderRadius: "12px",
    padding: "16px",
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
    marginBottom: "10px",
  },
  questionText: {
    fontSize: "16px",
    color: "#0f0c29",
    marginBottom: "16px",
    fontWeight: "600",
    lineHeight: "1.8",
    whiteSpace: "normal",
  },
  option: {
    padding: "10px 12px",
    margin: "5px 0",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "all 0.3s ease",
    display: "flex",
    alignItems: "center",
  },
  optionLabel: {
    fontSize: "14px",
    cursor: "pointer",
    flex: 1,
    margin: "0",
    color: "#2d3748",
    lineHeight: "1.8",
    whiteSpace: "normal",
  },
  navRow: {
    display: "flex",
    gap: "8px",
    flexWrap: "wrap",
    justifyContent: "space-between",
  },
  navBtn: {
    padding: "8px 14px",
    fontSize: "13px",
    border: "none",
    borderRadius: "8px",
    fontWeight: "600",
    transition: "all 0.3s ease",
  },
  submitBtn: {
    padding: "8px 18px",
    fontSize: "13px",
    backgroundColor: "#48bb78",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "600",
    boxShadow: "0 2px 8px rgba(72, 187, 120, 0.3)",
  },
  navigatorCard: {
    backgroundColor: "white",
    borderRadius: "12px",
    padding: "12px",
    boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
    marginTop: "10px",
  },
  navTitle: {
    margin: "0 0 8px 0",
    color: "#718096",
    fontSize: "11px",
    fontWeight: "600",
  },
  navGrid: { display: "flex", flexWrap: "wrap", gap: "5px" },
  navNum: {
    width: "32px",
    height: "32px",
    fontSize: "11px",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontWeight: "bold",
    transition: "all 0.3s ease",
  },
  legendRow: {
    display: "flex",
    gap: "12px",
    marginTop: "8px",
    fontSize: "10px",
    color: "#4a5568",
    flexWrap: "wrap",
  },
  timerWarning: {
    position: "fixed",
    bottom: "15px",
    right: "15px",
    left: "15px",
    backgroundColor: "#fc8181",
    color: "white",
    padding: "12px 18px",
    borderRadius: "10px",
    boxShadow: "0 4px 15px rgba(252, 129, 129, 0.4)",
    textAlign: "center",
    fontSize: "14px",
    fontWeight: "600",
    maxWidth: "400px",
    margin: "0 auto",
    animation: "pulse 1.5s ease-in-out infinite",
  },
};

const animStyles = `
  .math-text {
    line-height: 2;
  }

  /* Base math size */
  .katex {
    font-size: 1.35em;
  }

  /* Make fractions, sqrt, sums bigger and clearer */
  .katex .mfrac {
    font-size: 1.15em;
  }

  .katex .mfrac .frac-line {
    border-bottom-width: 0.08em;
  }

  .katex .sqrt > .root {
    font-size: 0.85em;
  }

  /* Superscripts and subscripts readable */
  .katex .msupsub {
    font-size: 0.85em;
  }

  /* Big operators like sum/product */
  .katex .mop {
    font-size: 1.1em;
  }

  /* Inline math inside option */
  .optionLabel .katex {
    font-size: 1.25em;
  }

  /* Inline math inside question stem */
  .questionText .katex,
  .math-text .katex {
    font-size: 1.3em;
  }

  @keyframes pulse {
    0% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.6; transform: scale(0.98); }
    100% { opacity: 1; transform: scale(1); }
  }
  @keyframes fadeInUp {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
  }
`;
